CREATE TABLE orders (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, order_id VARCHAR(100) NOT NULL, platform VARCHAR(20) NOT NULL, order_date DATE NOT NULL, customer_name VARCHAR(150), customer_phone VARCHAR(30), shipping_address TEXT, city VARCHAR(100), state VARCHAR(100), pincode VARCHAR(20), total_order_value NUMERIC(12,2) NOT NULL, commission NUMERIC(12,2) NOT NULL DEFAULT 0, shipping_charge NUMERIC(12,2) NOT NULL DEFAULT 0, other_charges NUMERIC(12,2) NOT NULL DEFAULT 0, net_amount NUMERIC(12,2) NOT NULL, order_status VARCHAR(20) NOT NULL DEFAULT 'PENDING', payment_status VARCHAR(20) NOT NULL DEFAULT 'PENDING', tracking_number VARCHAR(100), courier_partner VARCHAR(100), remarks TEXT, inventory_deducted BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT uq_orders_platform_order_id UNIQUE(platform,order_id));
CREATE TABLE order_items (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, order_id BIGINT NOT NULL REFERENCES orders(id), variant_id BIGINT NOT NULL REFERENCES product_variants(id), sku_snapshot VARCHAR(100) NOT NULL, product_name_snapshot VARCHAR(200) NOT NULL, quantity INTEGER NOT NULL CHECK(quantity>0), selling_price NUMERIC(12,2) NOT NULL CHECK(selling_price>=0), line_total NUMERIC(12,2) NOT NULL CHECK(line_total>=0));
CREATE INDEX idx_orders_date ON orders(order_date); CREATE INDEX idx_orders_status ON orders(order_status); CREATE INDEX idx_orders_tracking ON orders(tracking_number); CREATE INDEX idx_order_items_variant ON order_items(variant_id);
